<div class="page-title"><div><p class="eyebrow">POSLOVNI PREGLED</p><h1>Pregled poslovanja</h1><p><?=date('d.m.Y.')?> · Narudžbe, zalihe i naplata na jednom mjestu.</p></div></div>
<div class="business-kpis"><?php if(can('orders')):$orders=query("SELECT COALESCE(SUM(status IN ('new','preparing')),0) preparing,COALESCE(SUM(status IN ('shipped','completed')),0) shipped FROM orders")->fetch();foreach([['U pripremi',$orders['preparing'],'?page=orders&status=preparing'],['Poslano',$orders['shipped'],'?page=orders&status=shipped']] as [$title,$value,$url]):?><a class="kpi-card" href="<?=$url?>"><span><?=$title?></span><strong><?=$value?></strong></a><?php endforeach;endif;if(can('orders')&&can('payments')):$due=(float)query("SELECT COALESCE(SUM(total),0) FROM orders WHERE payment_status='unpaid' AND status NOT IN ('cancelled','returned')")->fetchColumn()+(float)query("SELECT COALESCE(SUM(total),0) FROM stock_exits WHERE reason='personal_sale' AND payment_status='unpaid' AND reversed_at IS NULL")->fetchColumn();?><a class="kpi-card" href="?page=reports"><span>Čeka naplatu</span><strong><?=money($due)?></strong></a><?php endif;if(inventoryEnabled()&&can('inventory')):$stock=query('SELECT COALESCE(SUM(stock),0) available,COALESCE(SUM(reserved),0) reserved,COALESCE(SUM(stock<=low_stock_threshold),0) low,COALESCE(SUM((stock+reserved)*purchase_price),0) value,COALESCE(SUM((stock+reserved)>0 AND purchase_price=0),0) unpriced FROM products')->fetch();?><a class="kpi-card" href="?page=inventory&filter=low"><span>Niske zalihe</span><strong><?=$stock['low']?></strong></a><?php endif;?></div>
<div class="business-layout"><?php if(can('orders')):?><section class="panel"><div class="section-heading"><h2>Za pakovanje i slanje</h2><a href="?page=orders&status=preparing">Pogledaj sve →</a></div><div class="table-scroll"><table><thead><tr><th>Narudžba</th><th>Kupac</th><th>Ukupno</th><th>Status</th><th>Sljedeći korak</th></tr></thead><tbody><?php $pending=query("SELECT * FROM orders WHERE status IN ('new','preparing') ORDER BY id DESC LIMIT 7")->fetchAll();foreach($pending as $o):?><tr><td><a href="?page=order&id=<?=$o['id']?>">#<?=$o['id']?></a></td><td><?=e($o['customer_name'])?></td><td><?=money((float)$o['total'])?></td><td><span class="status-badge status-preparing">U pripremi</span><?php if($o['payment_status']==='paid'):?><small class="cell-note">Naplaćeno</small><?php endif;?></td><td><a href="?page=order&id=<?=$o['id']?>"><?=$o['planned_delivery_id']?'Otvori i štampaj':'Pripremi dostavu'?> →</a></td></tr><?php endforeach;if(!$pending):?><tr><td colspan="5">Nema narudžbi koje čekaju pripremu.</td></tr><?php endif;?></tbody></table></div></section><?php endif;if(can('*')):$copies=backupList();$last=$copies[0]??null;?><section class="panel"><h2>Sigurnosne kopije</h2><div class="backup-health"><strong><?=$last?'Posljednja kopija: '.e(date('d.m. H:i',strtotime($last['created_at']))):'Još nema sigurnosne kopije'?></strong><small><?=$last?($last['checked_at']?'Provjera sadržaja uspješna':'Kopija čeka provjeru'):'Napravite prvu kopiju podataka.'?></small></div><div class="action-group"><a class="btn" href="?page=backups">Napravi backup</a><a class="btn secondary" href="?page=backups">Pregled vraćanja</a></div></section><?php endif;?></div>
<?php if(can('*')):?><section class="panel"><div class="section-heading"><h2>Dnevnik aktivnosti</h2><a href="?page=audit">Sve aktivnosti →</a></div><div class="table-scroll"><table><thead><tr><th>Vrijeme</th><th>Korisnik</th><th>Aktivnost</th><th>Obrazloženje</th></tr></thead><tbody><?php foreach(query('SELECT a.*,u.name FROM audit_log a LEFT JOIN users u ON u.id=a.user_id ORDER BY a.id DESC LIMIT 5')->fetchAll() as $row):?><tr><td><?=e(date('d.m. H:i',strtotime($row['created_at'])))?></td><td><?=e($row['name']??'Sistem / kupac')?></td><td><strong><?=e(activityLabel($row['action']))?></strong></td><td><?=e(activityDetails($row))?></td></tr><?php endforeach;?></tbody></table></div></section><?php endif;?>
<?php if(inventoryEnabled()&&can('inventory')):?><section class="panel"><h2>Pregled lagera</h2><div class="report-totals"><div><span>Slobodno</span><strong><?=$stock['available']?></strong></div><div><span>Rezervisano</span><strong><?=$stock['reserved']?></strong></div><div><span>Nabavna vrijednost</span><strong><?=money((float)$stock['value'])?></strong></div></div><?php if((int)$stock['unpriced']):?><p class="notice warning"><?=$stock['unpriced']?> artikala na stanju nema nabavnu cijenu. Vrijednost lagera je nepotpuna.</p><?php endif;?></section><?php endif;?>
<div class="dashboard-columns"><?php if(inventoryEnabled()&&can('inventory')):?><section class="panel"><div class="section-heading"><h2>Artikli za dopunu</h2><a class="text-link" href="?page=inventory&filter=low">Lager ↗</a></div><div class="table-scroll"><table><thead><tr><th>Artikal</th><th>Slobodno</th><th>Prag</th><th>Rezervisano</th></tr></thead><tbody><?php foreach(query('SELECT * FROM products WHERE stock<=low_stock_threshold ORDER BY stock,name LIMIT 8')->fetchAll() as $p):?><tr><td><?=e($p['name'])?><small class="cell-note"><?=e($p['sku'])?></small></td><td><span class="stock-warning"><?=$p['stock']?></span></td><td><?=$p['low_stock_threshold']?></td><td><?=$p['reserved']?></td></tr><?php endforeach;?></tbody></table></div></section><?php endif;if(can('orders')):?><section class="panel"><h2>Obavijesti o narudžbama</h2><div class="notification-list"><?php foreach(query('SELECT * FROM notifications ORDER BY id DESC LIMIT 6')->fetchAll() as $n):?><a href="?page=order&id=<?=$n['order_id']?>"><span class="notification-dot"></span><span><strong><?=e($n['message'])?></strong><small><?=e(date('d.m.Y. H:i',strtotime($n['created_at'])))?></small></span><b>↗</b></a><?php endforeach;?></div></section><?php endif;?></div>
<?php if(can('products')):?><div class="notice"><strong>Uređivanje naslovnice</strong><span>Na proizvodu označite „Velika naslovna objava“. Broj posljednjih odabranih artikala, vrijeme i efekat promjene uređuju se u Teme → Rotirajući prikaz.</span><a class="btn secondary" href="?page=products&placement=hero_live">Pregled velikih objava ↗</a></div><?php endif;?>

<?php if(can('orders')):?><section class="panel"><p class="eyebrow">POSLJEDNJIH 7 DANA</p><h2>Aktivnost naručivanja</h2><?php $days=[];for($i=6;$i>=0;$i--)$days[date('Y-m-d',strtotime('-'.$i.' days'))]=0;foreach(query('SELECT DATE(created_at) day,COUNT(*) n FROM orders WHERE created_at>=DATE_SUB(CURDATE(),INTERVAL 6 DAY) GROUP BY DATE(created_at)')->fetchAll() as $d)if(isset($days[$d['day']]))$days[$d['day']]=(int)$d['n'];$max=max(1,...array_values($days));?><div class="activity-chart"><?php foreach($days as $day=>$n):?><div class="activity-column"><span><?=$n?></span><div><i style="height:<?=max(3,round($n/$max*100))?>%"></i></div><small><?=date('d.m.',strtotime($day))?></small></div><?php endforeach;?></div><p class="field-help">Broj zaprimljenih narudžbi po danu, uključujući naknadno otkazane.</p></section><?php endif;?>
<?php if(can('orders')&&partnersReady()):?><section class="panel"><div class="section-heading"><h2>Poslovne narudžbe saradnika</h2><a href="?page=partner_orders">Sve poslovne narudžbe →</a></div><div class="table-scroll"><table><thead><tr><th>Narudžba</th><th>Saradnik</th><th>Vrijednost</th><th>Status</th></tr></thead><tbody><?php $partnerPending=query("SELECT * FROM partner_orders WHERE status IN ('new','preparing','partial','partly_returned') ORDER BY id DESC LIMIT 7")->fetchAll();foreach($partnerPending as $po):?><tr><td><a href="?page=partner_order&amp;id=<?=(int)$po['id']?>">B2B #<?=(int)$po['id']?></a></td><td><?=e($po['company'])?></td><td><?=partnerMoney(cents($po['total']))?></td><td><?=e(partnerStatus($po['status']))?></td></tr><?php endforeach;if(!$partnerPending):?><tr><td colspan="4">Nema poslovnih narudžbi koje čekaju obradu.</td></tr><?php endif;?></tbody></table></div></section><?php endif;?>
